#!/usr/bin/env python
# ── GENERATED by matsci-knowledge-base build/build_plugin.py — DO NOT EDIT (真源见 plugin.yaml) ──
r"""规范建议 3：更正流程的「全库同源检索」工具。

背景（根因三）
--------------
QC 实测：**一个更正平均有 3–7 处副本，其中常有 1–3 处在批次名单之外**。
实例：某「10 次迭代」的错误序号在 `index.md`、`outputs/组会汇报`、`sources/`
三处存活至最近才被发现（而 `concepts/` 早已修正）。

⇒ 任何数字/表述的更正，**必须随后扫描该表述的所有副本**并一并修正。
本工具就是这个步骤的执行器。

用法
----
  # 1) 查一个表述在全库的所有副本（更正前必跑）
  python tools/qc_same_text.py "355 配方"

  # 2) 只查数字（自动同时匹配千分位/无分隔/细空格等变体）
  python tools/qc_same_text.py --num 12708

  # 3) 看每个副本的上下文
  python tools/qc_same_text.py "355" -C 60

  # 4) 机器可读
  python tools/qc_same_text.py "355" --json

  # 5) 校验器自检（改动本脚本后必跑）
  python tools/qc_same_text.py --selftest

设计要点
--------
· **必须归一化后再匹配**——本库实测的十类假阴性形态（千分位、连字、断字、
  标点变体、LaTeX、细空格 U+2009…）会让「逐词 grep 零命中」的假象出现。
· **默认排除** `wiki/log.md`（历史存档）与 `wiki/.index/`（派生数据）。
· **同词不同义的假阳性**必须人工看上下文，工具只负责列全，不负责判义。
"""
import sys
import os
import re
import glob
import json
import argparse

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text  # noqa: E402
from kb_lib import console_encoding
console_encoding()

# 默认排除：历史存档与派生数据
# ⚠️ 扫描范围只有 `wiki/**/*.md`（见 scan()）——库根的 `.qc_backup_*`、`.qc/backups/`
#    永远不在范围内，写进排除表只会让 E2 静态检查误报「硬写 .qc/」（2026-10-31 移除）。
DEFAULT_EXCLUDE = ("wiki/log.md", ".index/", ".claude-rename/")

# —— 十类假阴性形态的归一化 ——
LIGATURES = {"ﬁ": "fi", "ﬂ": "fl", "ﬄ": "ffl", "ﬀ": "ff", "ﬃ": "ffi"}
# 细空格 U+2009 / U+202F / NBSP U+00A0 / 零宽 U+200B
SPACE_VARIANTS = "   ​‌‍⁠﻿"
# 各类连接号 → 统一为 -
DASHES = "‐‑‒–—―−﹘－"


def normalize(t):
    r"""把文本归一化到「可比形态」，用于**匹配**（不用于回写）。

    ⚠️ 顺序至关重要：**先 CRLF→LF，再删 `-\n`**。
       反序会漏配（QC 实测漏 166 次）。
    """
    t = t.replace("\r\n", "\n").replace("\r", "\n")
    t = re.sub(r"-\n", "", t)                 # 分行断字（须在 CRLF 归一之后）
    t = re.sub(r"-\s{2,}", "", t)             # `- ` 形式的分行断字
    for k, v in LIGATURES.items():
        t = t.replace(k, v)
    for ch in SPACE_VARIANTS:
        t = t.replace(ch, "")                 # 细空格等一律删除（数字内常见）
    t = t.replace(" ", "")
    for ch in DASHES:
        t = t.replace(ch, "-")
    # 千分位：1,234,567 / 1 234 567 → 1234567
    t = re.sub(r"(?<=\d)[,，](?=\d{3}\b)", "", t)
    return t.lower()


def variants_for_number(num):
    """为纯数字生成常见书写变体（千分位/细空格分隔）。"""
    num = num.replace(",", "").strip()
    out = {num}
    try:
        n = int(num)
    except ValueError:
        # 小数：只做原样
        return out
    out.add(f"{n:,}")
    out.add(f"{n:,}".replace(",", " "))        # 1 234 567（普通空格）
    out.add(f"{n:,}".replace(",", " "))   # 1 234 567（细空格）
    # 由于 normalize 会删空格，这些变体归一后其实相同——保留以便报告原文
    return out


def scan(needle, ctx=0, exclude=DEFAULT_EXCLUDE):
    """全库扫描，返回 [(文件, 行号, 命中行, 归一化命中)]"""
    n_norm = normalize(needle)
    if not n_norm:
        return []
    hits = []
    for f in glob.glob("wiki/**/*.md", recursive=True):
        rel = f.replace("\\", "/")
        if any(x in rel for x in exclude):
            continue
        try:
            t = read_text(f)
        except Exception:
            continue
        # 逐行匹配：先归一化整行再找 needle
        for i, line in enumerate(t.split("\n"), 1):
            if n_norm in normalize(line):
                shown = line if ctx <= 0 else line.strip()
                hits.append((rel, i, shown[:200], n_norm))
    return hits


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    按本库纪律，夹具必须**同时包含正例与反例**——只测「该过的过了」
    会漏掉「该报的没报」。以下每条都是实测踩过的坑。
    """
    ok = True
    cases = [
        # (输入, 期望归一化结果, 说明)
        ("1,234,567", "1234567", "千分位逗号须被删（否则假阴性）"),
        ("1 234 567", "1234567", "普通空格千分位"),
        ("1\u2009234\u2009567", "1234567", "细空格 U+2009 千分位"),
        ("\ufb01ne", "fine", "连字 ﬁ → fi"),
        ("abc\u2010def", "abc-def", "连字号 U+2010 → -"),
        ("ABC", "abc", "大小写不敏感"),
    ]
    for src, want, label in cases:
        got = normalize(src)
        print(f"  [{'ok' if got == want else 'FAIL'}] 正例 {label}: "
              f"{src!r} -> {got!r}")
        ok = ok and got == want

    # 反例：**断字归一必须先 CRLF→LF 再删 `-\n`**，顺序反了会漏 166 次（实测）
    got = normalize("nano-\nmaterial")
    want = "nanomaterial"
    print(f"  [{'ok' if got == want else 'FAIL'}] 正例 跨行断字: {got!r}")
    ok = ok and got == want
    got = normalize("nano-\r\nmaterial")
    print(f"  [{'ok' if got == want else 'FAIL'}] 正例 CRLF 断字（顺序敏感）: {got!r}")
    ok = ok and got == want

    # 反例：不相干的文本**不得**被判为同一表述（假阳性会让「同源」结论失效）
    got = normalize("完全不同的一段文字")
    same = got == normalize("1,234,567")
    print(f"  [{'ok' if not same else 'FAIL'}] 反例 不相干文本不误判为同源")
    ok = ok and not same

    # 正例：数字变体展开必须包含千分位写法
    vs = variants_for_number("1234567")
    has = "1,234,567" in vs
    print(f"  [{'ok' if has else 'FAIL'}] 正例 variants_for_number 含千分位 -> "
          f"{sorted(vs)[:2]}")
    ok = ok and has
    # 反例：小数不做整数变体展开，且不得崩溃
    vs = variants_for_number("1.5")
    got = vs == {"1.5"}
    print(f"  [{'ok' if got else 'FAIL'}] 反例 小数只做原样 -> {vs}")
    ok = ok and got

    # 正例：真实库扫描可跑通，且默认排除 log.md / .index
    hits = scan("1234567")
    print(f"  [info] 全库扫描可跑通 -> {len(hits)} 处")
    excluded_ok = all(not any(x in h[0] for x in ("wiki/log.md", ".index/"))
                      for h in hits)
    print(f"  [{'ok' if excluded_ok else 'FAIL'}] 正例 默认排除生效"
          f"（wiki/log.md 与 .index/）")
    ok = ok and excluded_ok

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="全库同源检索（更正流程必跑）")
    ap.add_argument("needle", nargs="?", help="要查的表述；配 --num 时为数字")
    ap.add_argument("--num", action="store_true", help="按数字查（自动展开千分位变体）")
    ap.add_argument("-C", "--context", type=int, default=0,
                    help="保留整行（默认截断）；>0 时显示整行")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    ap.add_argument("--include-log", action="store_true",
                    help="包含 wiki/log.md 历史存档（默认排除）")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    if not args.needle:
        ap.print_help()
        return 1

    exclude = DEFAULT_EXCLUDE
    if args.include_log:
        exclude = tuple(x for x in exclude if x != "wiki/log.md")

    needles = variants_for_number(args.needle) if args.num else {args.needle}

    seen = {}
    for nd in needles:
        for rel, ln, line, _n in scan(nd, args.context, exclude):
            seen[(rel, ln)] = line

    rows = sorted(seen.items())
    if args.json:
        print(json.dumps(
            [{"file": r[0], "line": r[1], "text": t} for (r, t) in rows],
            ensure_ascii=False, indent=1))
        return 0

    print(f"=== 全库同源检索：{args.needle!r} ===")
    print(f"归一化后 = {normalize(args.needle)!r}")
    print(f"命中 {len(rows)} 处\n")
    by_file = {}
    for (rel, ln), line in rows:
        by_file.setdefault(rel, []).append((ln, line))
    for rel in sorted(by_file):
        print(f"{rel}  ({len(by_file[rel])} 处)")
        for ln, line in by_file[rel][:8]:
            print(f"   L{ln:<5} {line[:150]}")
        if len(by_file[rel]) > 8:
            print(f"   ... 另 {len(by_file[rel]) - 8} 处")
    return 0


if __name__ == "__main__":
    sys.exit(main())
